import{_ as a,o as i,c as e,aO as n}from"./chunks/framework.vjUPZZJn.js";const o=JSON.parse('{"title":"GDB 生成 coredump：抓取运行中进程的内存快照","description":"","frontmatter":{"date":"2026-11-09T10:30:00.000Z","title":"GDB 生成 coredump：抓取运行中进程的内存快照","source":"[[1-知识/工具/调试/GDB 生成 Coredump 文件]]","tags":["工具","教程手册","GDB","调试"],"categories":["工具"],"permalink":"/pages/a8cc62"},"headers":[],"relativePath":"工具/GDB 生成 coredump：抓取运行中进程的内存快照.md","filePath":"工具/GDB 生成 coredump：抓取运行中进程的内存快照.md","lastUpdated":1794223026000}'),t={name:"工具/GDB 生成 coredump：抓取运行中进程的内存快照.md"};function l(p,s,h,r,d,k){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="gdb-生成-coredump-抓取运行中进程的内存快照" tabindex="-1">GDB 生成 coredump：抓取运行中进程的内存快照 <a class="header-anchor" href="#gdb-生成-coredump-抓取运行中进程的内存快照" aria-label="Permalink to &quot;GDB 生成 coredump：抓取运行中进程的内存快照&quot;">​</a></h1> <p>线上进程出了问题但没崩溃——内存缓慢增长、状态诡异地卡住、某个线程疑似死锁——这时候最想要的是一份「当时的完整现场」，又不能 kill 进程等它吐 core。GDB 的 <code>generate-core-file</code> 命令可以在 attach 到运行中进程后直接生成 coredump 文件，效果等同于进程崩溃时系统自动落盘的 core，之后完全可以离线慢慢分析。本文给出三种生成方式和一个容易踩的参数陷阱。</p> <h2 id="方法一-gdb-交互模式" tabindex="-1">方法一：GDB 交互模式 <a class="header-anchor" href="#方法一-gdb-交互模式" aria-label="Permalink to &quot;方法一：GDB 交互模式&quot;">​</a></h2> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># attach 到目标进程</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 生成 coredump（可指定文件名）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">generate-core-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/core.myapp</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 不指定文件名则默认 core.&lt;PID&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 生成完毕后 detach 退出</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">detach</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">quit</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>适合需要先观察一下进程状态（线程栈、变量）再决定是否快照的场景。</p> <h2 id="方法二-一行命令-非交互" tabindex="-1">方法二：一行命令（非交互） <a class="header-anchor" href="#方法二-一行命令-非交互" aria-label="Permalink to &quot;方法二：一行命令（非交互）&quot;">​</a></h2> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -batch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;generate-core-file /tmp/core.myapp&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;detach&quot;</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>-batch</code> 配合 <code>-ex</code> 不进交互界面，适合脚本化批量操作。</p> <h2 id="方法三-gcore" tabindex="-1">方法三：gcore <a class="header-anchor" href="#方法三-gcore" aria-label="Permalink to &quot;方法三：gcore&quot;">​</a></h2> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 直接在 shell 中生成，无需手动进入 GDB attach</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gcore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/core.myapp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 注意：-o 指定的是文件名前缀，实际生成 /tmp/core.myapp.&lt;PID&gt;</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>gcore</code> 本质上是 GDB 的封装（内部同样会 ptrace attach 暂停目标进程），效果相同，使用最简洁。日常排查推荐它。</p> <p><strong>陷阱就在 <code>-o</code> 参数</strong>：它接受的是文件名<strong>前缀</strong>而不是完整文件名，gcore 会自动追加 <code>.PID</code> 后缀（依据 <code>man gcore</code>）。指望拿到 <code>/tmp/core.myapp</code> 的脚本，实际拿到的是 <code>/tmp/core.myapp.12345</code>，路径拼错就会以为生成失败。想精确控制完整文件名，用方法一或方法二。</p> <h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2> <ul><li><strong>进程暂停</strong>：生成 coredump 期间进程会被暂停（STOP），进程越大耗时越长，<strong>生产环境慎用</strong>；</li> <li><strong>磁盘空间</strong>：coredump 文件大小约等于进程的 RSS，落盘前确认目标路径空间充足；</li> <li><strong>权限</strong>：需要对目标进程有 ptrace 权限（同用户或 root），受 Yama <code>ptrace_scope</code> 限制的环境需先放开；</li> <li><strong>进程恢复</strong>：生成完成后进程自动恢复运行，不受影响；</li> <li><strong>ulimit</strong>：<code>generate-core-file</code> 和 <code>gcore</code> 不受 <code>ulimit -c</code> 限制——它们由 GDB 直接写文件，不走内核的 core dump 管道。</li></ul> <h2 id="离线分析" tabindex="-1">离线分析 <a class="header-anchor" href="#离线分析" aria-label="Permalink to &quot;离线分析&quot;">​</a></h2> <p>拿到 coredump 后与二进制一起打开：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/binary</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/core.myapp</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 常用分析命令</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bt</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # 查看调用栈</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">info</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> threads</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 查看所有线程</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">thread</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bt</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 所有线程调用栈</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>如果发布包里的二进制是 stripped 的，堆栈里只有地址没有函数名，需要配合调试符号包——可以参考《GDB attach 加载带调试信息的共享库符号》里的符号加载方法。</p> <h2 id="三种方式对比" tabindex="-1">三种方式对比 <a class="header-anchor" href="#三种方式对比" aria-label="Permalink to &quot;三种方式对比&quot;">​</a></h2> <table tabindex="0"><thead><tr><th>方法</th> <th>优点</th> <th>缺点</th></tr></thead> <tbody><tr><td>GDB 交互</td> <td>可在生成前先检查进程状态</td> <td>需要手动操作</td></tr> <tr><td>GDB -batch</td> <td>可脚本化，一行搞定</td> <td>无法先检查</td></tr> <tr><td>gcore</td> <td>最简洁</td> <td><code>-o</code> 是前缀不是文件名，功能单一</td></tr></tbody></table> <h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2> <ul><li>未崩溃的进程也能拿「完整现场」：attach 后 <code>generate-core-file</code> 或直接 <code>gcore</code></li> <li><code>gcore -o</code> 是前缀语义，产物会带 <code>.PID</code> 后缀，脚本里别拼错路径</li> <li>快照期间进程暂停，大进程在生产环境要评估停顿代价</li> <li>产物不受 <code>ulimit -c</code> 影响，但需要 ptrace 权限和约等于 RSS 的磁盘空间</li></ul>`,39)])])}const g=a(t,[["render",l]]);export{o as __pageData,g as default};
